class MyCircularQueue {
    vector<int> data;
    int front;
    int rear;
    int count;
    int cap;
public:
    MyCircularQueue(int k) : data(k), front(0), rear(0), count(0), cap(k) {}

    bool enQueue(int value) {
        if (count == cap) return false;
        if (count == 0) {
            front = 0;
            rear = 0;
        } else {
            rear = (rear + 1) % cap;
        }
        data[rear] = value;
        count++;
        return true;
    }

    bool deQueue() {
        if (count == 0) return false;
        front = (front + 1) % cap;
        count--;
        return true;
    }

    int Front() {
        return count == 0 ? -1 : data[front];
    }

    int Rear() {
        return count == 0 ? -1 : data[rear];
    }

    bool isEmpty() {
        return count == 0;
    }

    bool isFull() {
        return count == cap;
    }
};
